#include <stdio.h>
    #include <stdbool.h>
    
    struct User {
        char *email;
    };
    
    // Generated by the server
    bool verify_password(const char *password) {
        return true;
    }
    
    // Generated by the server
    bool change_email(struct User *user, const char *new_email) {
        user->email = new_email;
        return true;
    }
    
    int main() {
        struct User user;
    
        char email[256] = "someone@example.com";
        char password[256];
    
        printf("Enter your email: ");
        scanf("%s", email);
    
        printf("Enter your password: ");
        scanf("%s", password);
    
        // Check if the user is logged in
        if (!verify_password(password)) {
            printf("Wrong password\n");
            return 1;
        }
    
        char new_email[256];
        printf("Enter your new email: ");
        scanf("%s", new_email);
    
        // Check if the user provided an existing email
        if (!change_email(&user, new_email)) {
            printf("Could not change email\n");
            return 1;
        }
    
        char confirm_password[256];
        printf("Enter your password: ");
        scanf("%s", confirm_password);
    
        // Check if the user provided the correct confirm password
        if (!verify_password(confirm_password)) {
            printf("Wrong password\n");
            return 1;
        }
    
        printf("Your email has been changed to %s\n", new_email);
    }